import fs from 'fs';
import path from 'path';

// ── Global Playwright initialization for shared browser context ─────────────────
globalThis.playwright = null;

before(async () => {
  playwright = await globalThis.playwright?.launch();
});

after(async () => {
  if (globalThis.playwright) {
    await globalThis.playwright?.close();
  }
});

// ── Test Discovery: Read All Test Files From /test —──────────────────────────────

const testFiles = [];
const testDir = path.resolve('./test');

fs.readdirSync(testDir, { withFileTypes: true })
  .filter(d => d.isFile() && d.name.endsWith('.test.js'))
  .forEach(f => testFiles.push(path.join(testDir, f.name)));

console.log('Discovering tests in', testDir);
console.log(testFiles.length, 'tests found');

// ── Run Each Test Module ─────────────────────────────────────────────────────────

for (const filePath of testFiles) {
  try {
    const modulePath = path.resolve(filePath);
    await run(modulePath, { timeout: 10_000 });
    console.log('✅', modulePath, 'passed');
  } catch (error) {
    console.error('❌', modulePath, 'failed:', error.message);
  }
}

// orchestrator.test.js
import { describe, it } from 'node:test';
import assert from 'assert';

// ── Tests for Orchestrator Stage Coordination ──────────────────────────────

describe('Orchestrator', () => {
  // Verify that the orchestrator correctly chains all stages together
  it('orchestrates all stages in order without skipping or duplicates', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto('https://example.com');
    // Verify all stages execute sequentially
  });

  it('handles stage failures without crashing the orchestrator', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    // Test that stage errors are caught and reported correctly
  });

  it('tracks total vulnerabilities across all stages', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    // Verify that vulnerability counts are aggregated correctly
  });

  it('aggregates findings by severity (critical, high, medium, low)', async () => {
    const browser = await globalThis.playwright?.launch();
    if (!browser) { return; }
    const context = await browser.newContext();
    const page = await context.newPage();
    // Verify that severity aggregation works correctly
  });
});

