import chalk from 'chalk';
import fs from 'fs';
import path from 'path';

export interface ScanResult {
  scanId: string;
  startTime: Date;
  endTime: Date;
  targetUrl: string;
  results: Array<{
    vulnType: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    status: 'passed' | 'failed';
    evidence: string;
    stepsToReproduce: string[];
    remediationAdvice: string[];
  }>;
  summary: {
    totalVulnerabilities: number;
    bySeverity: Array<{ severity: string; count: number }>;
  };
}

export function generateReport(scanResults: ScanResult[]): void {
  const outputDir = './outputs';

  // Ensure output directory exists
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const now = new Date().toISOString();

  // Aggregate summary across all scan results
  const summary = scanResults.reduce(
    (acc, res) => {
      for (const vuln of res.results) {
        if (!acc[vuln.severity]) { acc[vuln.severity] = 0; }
        acc[vuln.severity]++;
      }
      return acc;
    },
    { low: 0, medium: 0, high: 0, critical: 0 }
  );

  const htmlPath = path.join(outputDir, 'report.html');
  const mdPath = path.join(outputDir, 'report.md');
  const jsonPath = path.join(outputDir, 'report.json');

  // Generate HTML report
  const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>OWASP TOP 10 Penetration Test Report</title>
  <style>
