      --critical: #d32f2f;
      --high: #f57c00;
      --medium: #1976d2;
      --low: #4caf50;
    }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      line-height: 1.6;
      max-width: 800px;
      margin: 0 auto;
