      margin-bottom: 20px;
    }
    .summary {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
      margin: 20px 0;
    }
    .severity-box {
      padding: 15px;
      border-radius: 8px;
      text-align: center;
      color: #fff;
      font-weight: bold;
