    totalVulnerabilities: results.filter(r => r.status === 'failed').length,
    critical: 0, high: 0, medium: 0, low: 0,
  };

  results.forEach(r => {
    if (r.severity && !['low'].includes(r.severity)) {
      summary[r.severity]++;
    }
  });

