// ── Reconnaissance helper ─────────────────────────────────────────────────────

interface ReconResult {
  url: string;
  title: string;
  metaTags: Array<{ name: string; content?: string }>;
  favicon: boolean;
  techStackDetected: string[];
  endpoints: Array<{ path: string; method: 'GET' | 'POST' }>;
}

async function scanRecon(page, url: string): Promise<string> {
  await page.goto(url, { waitUntil: 'networkidle' });

  const title = await page.title();
  let viewport = await page.locator('meta[name="viewport"]')
    .getAttribute('content');
  if (!viewport) viewport = 'N/A';
  let description = await page.locator('meta[name="description"]')
    .getAttribute('content');
  if (!description) description = 'N/A';

  let favicon = false;
  try {
    favicon = await page.locator('link[rel="icon"], link[rel="shortcut icon"]')
      .count() > 0;
  } catch {}

  const jsFiles: string[] = [];
  try {
    const srcs = await page.evaluate(() => {
      return Array.from(document.scripts)
        .map(s => s.src)
        .filter(Boolean);
    });
    jsFiles.push(...srcs);
  } catch {}

  let techStack: string[] = [];
  for (const src of jsFiles) {
    if (src.includes('react')) techStack.push('React');
    if (src.includes('vue')) techStack.push('Vue.js');
    if (src.includes('angular')) techStack.push('Angular');
    if (src.includes('ember')) techStack.push('Ember');
  }

  let apiEndpoints: Array<{path: string; method: 'GET' | 'POST'}> = [];
  try {
    const html = await page.content();
    // Simple heuristic: look for common API routes
    if (html.includes('/api')) apiEndpoints.push({ path: '/api', method: 'GET' });
    if (html.includes('/graphql')) apiEndpoints.push({ path: '/graphql', method: 'POST' });
  } catch {}

  return JSON.stringify({
    url,
    title,
    metaTags: [{ name: 'viewport', content: viewport }, { name: 'description', content: description }],
    favicon,
    techStackDetected: techStack,
    endpoints: apiEndpoints,
  });
}

// ── Vulnerability Scan helper ──────────────────────────────────────────────────

async function runVulnTests(page, url: string): Promise<any[]> {
  const results = [];

  // A01 — SQL Injection
  results.push(await testSQLi(page, url));

  // A02 — Broken Authentication (session hijacking)
  results.push(await testSessionHijacking(page, url));

  // A04 — Cross-Site Scripting
  results.push(await testReflectedXSS(page, url));

  // A05 — Broken Access Control (IDOR)
  results.push(await testIDOR(page, url));

  return results;
}

